# -*- coding: utf-8 -*-
"""
Filter nodes by protocol (vless, hysteria2, mieru, masque) and push to Gist.
Used as a post-processing step in the GitHub Actions workflow.
"""
import json
import os
import subprocess
import sys
import base64
import re

GIST_ID = "942e3c9de1396e6b3bf4afab0f054349"
TARGET_PROTOCOLS = {"vless", "hysteria2", "mieru", "masque"}
INPUT_FILE = "output/checked/all.yaml"
OUTPUT_FILE = "output/filtered_nodes.json"

def load_yaml_nodes(filepath):
    """Load nodes from a YAML file generated by aggregator000."""
    try:
        import yaml
        with open(filepath, 'r', encoding='utf-8') as f:
            data = yaml.safe_load(f)
        if isinstance(data, dict) and 'proxies' in data:
            return data['proxies']
        return []
    except Exception as e:
        print(f"Error loading YAML: {e}")
        return []

def filter_by_protocol(nodes):
    """Keep only nodes of target protocols."""
    filtered = []
    for node in nodes:
        p_type = node.get('type', '').lower()
        if p_type in TARGET_PROTOCOLS:
            filtered.append(node)
    print(f"Total nodes: {len(nodes)}")
    print(f"Filtered nodes (vless/hy2/mieru/masque): {len(filtered)}")
    return filtered

def push_to_gist(filename, content):
    """Push content to a specific file in the Gist."""
    token = os.environ.get("PUSH_TOKEN") or os.environ.get("GH_TOKEN")
    if not token:
        print("Error: PUSH_TOKEN or GH_TOKEN not set")
        return False
    
    b64_content = base64.b64encode(content.encode('utf-8')).decode('utf-8')
    
    # Get current SHA if file exists
    sha = None
    try:
        cmd = [
            "gh", "api", 
            f"gists/{GIST_ID}/files/{filename}"
        ]
        # This API doesn't exist directly for single file, we get whole gist
        r = subprocess.run(["gh", "api", f"gists/{GIST_ID}"], capture_output=True, text=True)
        if r.returncode == 0:
            gist_data = json.loads(r.stdout)
            files = gist_data.get("files", {})
            if filename in files:
                sha = files[filename].get("sha")
    except:
        pass

    payload = {
        "files": {
            filename: {
                "content": content
            }
        }
    }
    if sha:
        # For updating, we just send content, gh api handles it if we use PATCH on gist
        pass 

    # Use gh gist edit is simpler but requires file on disk. Let's write to disk first.
    tmp_file = f"/tmp/{filename}"
    with open(tmp_file, 'w', encoding='utf-8') as f:
        f.write(content)
    
    cmd = ["gh", "gist", "edit", GIST_ID, "-a", tmp_file]
    env = os.environ.copy()
    # gh uses logged in user, so token isn't needed for gh command if logged in. 
    # But in Actions, we rely on gh auth login with token.
    r = subprocess.run(cmd, capture_output=True, text=True)
    if r.returncode != 0:
        print(f"Failed to push to Gist: {r.stderr}")
        return False
    print(f"Successfully pushed {filename} to Gist {GIST_ID}")
    return True

def main():
    if not os.path.exists(INPUT_FILE):
        print(f"Input file {INPUT_FILE} not found.")
        # Try alternative location
        alt = "output/all.yaml"
        if os.path.exists(alt):
            INPUT_FILE = alt
        else:
            sys.exit(1)

    nodes = load_yaml_nodes(INPUT_FILE)
    if not nodes:
        print("No nodes found.")
        sys.exit(0)

    filtered = filter_by_protocol(nodes)
    
    if not filtered:
        print("No matching nodes found after filtering.")
        # Create empty file to indicate status
        push_to_gist("filtered_empty.txt", "No vless/hysteria2/mieru/masque nodes found.")
        sys.exit(0)

    # Convert back to YAML format for Mihomo compatibility
    output_yaml = "# Filtered Nodes: vless, hysteria2, mieru, masque\nproxies:\n"
    import yaml
    # Custom representer to keep flow style for proxies if desired, but block is safer for readability
    yaml_str = yaml.dump({"proxies": filtered}, allow_unicode=True, default_flow_style=False)
    
    success = push_to_gist("filtered_nodes.yaml", yaml_str)
    if success:
        print("Done.")
    else:
        sys.exit(1)

if __name__ == "__main__":
    main()